#!/usr/bin/env node
// Turns the test bench's fixtures (testbench/fixtures/*.md) into a module the
// UI tests can import: the test kit runs tests with no file access, and imports
// only code files. One source for the manual bench and the automated tests.
//
// Also copies the test bench's neighbour mod into the tests: a test may import
// only files inside the plugin's folder, and the neighbour lives in testbench/
// so it can be loaded by hand with --plugin-dir.
//
//   node scripts/fixtures.mjs           write the generated files
//   node scripts/fixtures.mjs --check   fail if they are not what testbench/ gives

import { readdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const source = join(root, 'testbench', 'fixtures')
const target = join(root, 'hosts', 'claude-code', 'tests', 'fixtures.generated.ts')
const neighbourSource = join(root, 'testbench', 'neighbour-mod', 'hooks', 'register.tsx')
const neighbourTarget = join(root, 'hosts', 'claude-code', 'tests', 'neighbour.generated.tsx')

const SLEEP = /^<<sleep (\d+)>>$/

// A fixture's reply, split into the pieces a real run produces: a `<<sleep N>>`
// line is a tool call, so the text before and after it are separate messages.
// Its checks are the list under "What to check".
function parse(text) {
  const pieces = []
  let current = []
  for (const line of text.split('\n')) {
    if (SLEEP.test(line.trim())) {
      pieces.push(current.join('\n').trim())
      current = []
    } else {
      current.push(line)
    }
  }
  pieces.push(current.join('\n').trim())

  const checks = []
  let inChecks = false
  for (const line of text.split('\n')) {
    if (/^#{1,6}\s+What to check\s*$/.test(line)) inChecks = true
    else if (/^#{1,6}\s/.test(line)) inChecks = false
    else if (inChecks && line.startsWith('- ')) checks.push(line.slice(2).trim())
  }
  return { pieces: pieces.filter(Boolean), checks }
}

const names = readdirSync(source)
  .filter(f => f.endsWith('.md'))
  .sort()
const body = names
  .map(file => {
    const { pieces, checks } = parse(readFileSync(join(source, file), 'utf8'))
    return `  ${JSON.stringify(file.replace(/\.md$/, ''))}: {
    pieces: ${JSON.stringify(pieces, null, 2).replace(/\n/g, '\n    ')},
    checks: ${JSON.stringify(checks, null, 2).replace(/\n/g, '\n    ')},
  },`
  })
  .join('\n')

const out = `// GENERATED by scripts/fixtures.mjs from testbench/fixtures/*.md — do not edit.
// Run \`node scripts/fixtures.mjs\` after changing a fixture.

export type Fixture = { readonly pieces: readonly string[]; readonly checks: readonly string[] }

export const FIXTURES: Readonly<Record<string, Fixture>> = {
${body}
}
`

const neighbour = `// GENERATED by scripts/fixtures.mjs from testbench/neighbour-mod/hooks/register.tsx — do not edit.
// Run \`node scripts/fixtures.mjs\` after changing the neighbour mod.

${readFileSync(neighbourSource, 'utf8')}`

const outputs = [
  [target, out],
  [neighbourTarget, neighbour],
]

if (process.argv.includes('--check')) {
  const stale = outputs.filter(([file, text]) => !existsSync(file) || readFileSync(file, 'utf8') !== text)
  if (stale.length) {
    for (const [file] of stale) console.error(`${file.slice(root.length + 1)} is out of date`)
    console.error('run `node scripts/fixtures.mjs`')
    process.exit(1)
  }
  console.log('generated test files up to date')
} else {
  for (const [file, text] of outputs) writeFileSync(file, text)
  console.log(`wrote ${names.length} fixtures and the neighbour mod into hosts/claude-code/tests/`)
}
